<?php namespace App\Controllers;
class Reports extends BaseController{
 public function index(){if($r=$this->mustLogin())return $r;$month=$this->request->getGet('month')?:date('Y-m');$db=db_connect();$rows=$db->query("SELECT m.id,m.code,m.description,m.production_plan,COALESCE(ms.opening_stock,0) opening_stock,COALESCE(SUM(d.receipt_qty),0) receipts,COALESCE(SUM(d.issued_qty),0) issued,(COALESCE(ms.opening_stock,0)+COALESCE(SUM(d.receipt_qty),0)-COALESCE(SUM(d.issued_qty),0)) closing_stock,COALESCE(ms.physical_stock_month_end,0) physical_stock,((COALESCE(ms.opening_stock,0)+COALESCE(SUM(d.receipt_qty),0)-COALESCE(SUM(d.issued_qty),0))-COALESCE(ms.physical_stock_month_end,0)) difference,COALESCE(SUM(d.production_output_qty),0) production,COALESCE(SUM(d.in_process_rejection_qty+d.other_rejection_qty),0) rejection,COALESCE(SUM(d.transfer_out_qty),0) transfer,COALESCE(SUM(d.samples_qty),0) samples,CASE WHEN m.production_plan>0 THEN (COALESCE(SUM(d.production_output_qty),0)/m.production_plan)*100 ELSE NULL END plan_actual FROM materials m LEFT JOIN monthly_stock ms ON ms.material_id=m.id AND ms.month_key=? LEFT JOIN daily_entries d ON d.material_id=m.id AND d.month_key=? GROUP BY m.id,ms.id ORDER BY m.id",[$month,$month])->getResultArray();return $this->render('reports/index',['pageTitle'=>'Monthly Report','month'=>$month,'rows'=>$rows]);}}
